function parse(p){const text=p.original;const matches=[...text.matchAll(/^(?:第[零〇一二三四五六七八九十百千万\d]+[章节回卷部][^\n]*|(?:Chapter\s+\d+|场景\s*\d+|场次\s*\d+|第[一二三四五六七八九十\d]+场)[^\n]*)/gmi)];p.chapters=[];if(matches.length){if(matches[0].index>0)p.chapters.push({id:id('part'),title:'前言',start:0,end:matches[0].index});matches.forEach((m,i)=>p.chapters.push({id:id('part'),title:m[0].trim(),start:m.index,end:matches[i+1]?.index??text.length}));}else p.chapters=[{id:id('part'),title:'全文',start:0,end:text.length}];p.chapterIds=p.chapters.slice(0,1).map(x=>x.id);p.contentType=/^(场景|场次|第.{1,4}场)/m.test(text)?'screenplay':p.chapters.length>1||count(text)>4000?'novel':'story';p.sourceRevision++;p.confirmed=false;return p.chapters;}
function rangeText(p){if(p.scope==='fragment')return p.fragment;if(p.scope==='chapter')return p.chapters.filter(c=>p.chapterIds.includes(c.id)).map(c=>p.original.slice(c.start,c.end)).join('\n\n');return p.original;}
function processingWarning(p){const n=count(rangeText(p)),max=targets[p.target][1];if(p.processing==='expand'&&n>max)return `当前范围 ${n} 字，超过目标上限 ${max} 字。请选择较短片段扩写，或明确改用“精简压缩 / 改编剧本”；不会自动截短。`;if(p.processing!=='polish'&&n>4000)return '当前范围超过本轮约4000字建议。原文完整保留，请选择章节或片段逐集处理。';return '';}
function isSample(p){return p.original.trim()===Sample.seed||p.original===Sample.novel||p.original===Sample.screenplay;}
function directions(p){const premise=rangeText(p).trim();if(!premise)throw Error('先输入灵感。');if(count(premise)>1000)throw Error('这段内容较长，请使用“已有内容”确认处理范围。');if(premise===Sample.seed)return cp(Sample.directions);return ['人物选择','事件推进','关系转折'].map((v,i)=>({title:v+' · 结构方向演示',body:`你的起点是：“${premise}”。这个方向把${v}作为组织重点，不替你推断尚未提供的人物身份和结局。先保留这一事实，让主角面对一个与原始设定直接相关、但尚待你确认的选择；随后安排一次尝试，把行动的后果放到读者面前。中段可以让另一个人物提出不同意见，使故事不只依赖背景介绍，而是通过场景和对话呈现分歧。转折应来自已经建立的条件，不突然引入万能帮助。最后用一个可见的动作回应开头，让人物的决定带来具体变化，而不只用旁白宣布成长。你可以在下一步补写人物姓名、关系、阻力和结局，再把这份方向改成属于你的故事。这是围绕原文的策划结构演示，未连接模型，不代表已经理解或自动完成情节。${i===0?'优先检查主角想要什么、愿意付出什么。':i===1?'优先检查每个事件如何引起下一个事件。':'优先检查人物关系在行动前后发生了什么变化。'}`}));}
function selectDirection(p,i){p.chosen=i;p.story=p.original.trim()===Sample.seed&&i===0?Sample.story:rangeText(p)+'\n\n【已选策划方向 · 可编辑】\n'+p.directions[i].body;touch(p,'story');p.stage=2;}
function process(p){const w=processingWarning(p);if(w)throw Error(w);const t=rangeText(p);if(!t.trim())throw Error('处理范围不能为空。');p.story=t;p.processingNote=p.processing==='polish'?'已保留原长与原意；未接模型，请在故事稿中直接润色。':'未接模型，已完整带入选中范围；请手动完成'+({expand:'补充扩写',compress:'精简压缩',adapt:'剧本改编'}[p.processing]||'编辑')+'，不会伪造自动完成。';touch(p,'story');}
function touch(p,level){if(p.revisions[level]!==undefined)p.revisions[level]++;p.updatedAt=new Date().toISOString();}
function addCharacter(p,name='',aliases=''){const all=[name,...aliases.split(/[、,，]/)].map(x=>x.trim()).filter(Boolean);const found=p.characters.find(c=>[c.name,...c.aliases.split(/[、,，]/)].some(x=>all.includes(x.trim())));if(found)return found;const c={id:id('person'),name,aliases,identity:'待确认身份',relation:'',state:''};p.characters.push(c);return c;}
