function writeEpisode(p,epId){if(p.scripts[epId])return p.scripts[epId];const e=p.outline.find(x=>x.id===epId);if(!e)throw Error('先选择一集大纲。');if(count(e.events)>4000)throw Error('本集超过约4000字建议，请回大纲拆分本集后逐集整理，原文不会截断。');const chunks=e.events.split(/\n\s*\n/).filter(Boolean);const s={episodeId:epId,scenes:chunks.map((x,i)=>scene(x,i,p)),basedOutline:p.revisions.outline,createdAt:new Date().toISOString(),demo:true};if(!s.scenes.length)s.scenes=[scene(e.events,0,p)];p.scripts[epId]=s;p.selectedEpisode=epId;p.selectedScene=0;return s;}
