function asset(p){if(!Object.keys(p.scripts).length)throw Error('请先整理或编辑至少一集剧本。');return {...bodyForHandoff(p),type:'cimora-script-asset',assetId:p.savedAssetId||id('script-asset'),savedAt:new Date().toISOString()};}
