function assetStale(p,a){const fields=['title','original','story','settings','characters','places','props','facts','analysis','outline','scripts','sourceName','scope','chapterIds','fragment','overallOutline','episodeDuration','plannedEpisodes','importRequest','workAssistant','outlineSettings','outlinePhases','outlineArchives','importAnalysis','sourceAuthority','sourceBaseline','sourceNeedsReview'];return !a||fields.some(k=>JSON.stringify(p[k])!==JSON.stringify(a[k]));}
