function ideaChoose(p,i){const d=ideaDesk(p);if(!d.plans[i])throw Error('请选择有效方案。');if(d.selected===i)return;d.selected=i;d.undo=null;d.messages.push({role:'assistant',text:'正在完善方案'+(i+1)+'：'+d.plans[i].title+'。说说你想怎样调整。'});}
function ideaRefine(p){const d=ideaDesk(p),plan=d.plans[d.selected],text=d.draft.trim();if(!plan)throw Error('先在右侧选择一个方向。');if(!text)throw Error('请写下这次希望调整的内容。');const rules={characters:/人物|主角|配角|角色|反派|关系/,conflict:/冲突|阻力|矛盾|对抗|代价/,ending:/结局|结尾|收尾|开放式/,world:/世界|背景|设定|时间|地点|环境/,synopsis:/梗概|情节|开端|中段|剧情/},labels={characters:'人物',conflict:'冲突',ending:'结局',world:'世界观',synopsis:'梗概',requirements:'方案补充要求'};let keys=Object.keys(rules).filter(k=>rules[k].test(text));const known=keys.length>0;if(!known)keys=['requirements'];const changes=keys.map(key=>{const before=plan[key]||'',addition='\n\n补充要求（待融合）：'+text;plan[key]=before+addition;return {key,before,after:plan[key],addition};});d.undo={index:d.selected,changes};d.messages.push({role:'user',text},{role:'assistant',text:known?'已将要求原句补充到'+keys.map(k=>labels[k]).join('、')+'，待你融合；其他内容保留。':'已保存为方案补充要求，待融合；暂未判断应修改哪部分。'});d.draft='';}
function ideaUndo(p){const d=ideaDesk(p),u=d.undo;if(!u)throw Error('没有可撤回的调整。');const plan=d.plans[u.index],changes=u.changes||[{key:u.key,before:u.before}];let kept=false;for(const c of changes){if(c.after!==undefined&&plan[c.key]===c.after)plan[c.key]=c.before;else if(c.addition&&plan[c.key]?.slice(c.before.length,c.before.length+c.addition.length)===c.addition)plan[c.key]=plan[c.key].slice(0,c.before.length)+plan[c.key].slice(c.before.length+c.addition.length);else kept=true;}d.undo=null;d.messages.push({role:'assistant',text:kept?'已撤回可确认的本轮补充；发生后续编辑的内容保留，请手动核对。':'已撤回本轮补充，其他手改保留。'});}
function ideaAdopt(p,replace=false){if(p.story.trim()&&!replace)throw Error('已有稿件，请确认替换；原稿可撤回。');const prior={story:p.story,meta:storyMeta(p)};const d=ideaDesk(p),plan=d.plans[d.selected];if(!plan||!plan.synopsis.trim())throw Error('请选择并填写方案梗概。');p.title=plan.title.trim()||p.title;p.chosen=d.selected;p.adoptedPlan=cp(plan);for(const key of ['audience','genre','core','style'])if(plan[key]?.trim())p.settings[key]=plan[key];p.story=[plan.synopsis,'核心亮点：'+(plan.hook||'待补充'),'核心设定：'+(plan.core||'待补充'),'人物：'+plan.characters,'世界观：'+plan.world,'核心冲突：'+plan.conflict,'结局：'+plan.ending].join('\n\n');p.storyDraft={kind:'structure',status:'ready',planTitle:plan.title,generatedTarget:p.target,undo:prior};p.processingNote='本机演示：已携带当前方案整理结构稿，尚非完整正文；请继续写作。';touch(p,'story');p.analysisConfirmed=false;p.stage=2;}
