function preferenceState(p,store,key){const old=store[key];return old&&old.value===p.settings[key]?old:{legacy:p.settings[key]||'',tags:[],value:p.settings[key]||''};}
function preferenceToggle(p,store,key,id,label){const v=preferenceState(p,store,key);v.tags=v.tags.some(t=>t.id===id)?v.tags.filter(t=>t.id!==id):v.tags.some(t=>t.label===label)?v.tags:[...v.tags,{id,label}];v.value=[v.legacy,...v.tags.map(t=>t.label)].filter(Boolean).join('、');p.settings[key]=v.value;store[key]=v;}
function preferenceAppend(p,label){if(!p.settings.core.includes(label))p.settings.core+=(p.settings.core?'；':'')+label;}
function ideaEntryStage(p){return p.stage<2?p.stage:p.directions.length&&!p.ideaDesk?1:0;}
function navigation(p){const idea=p.origin==='idea',labels=idea?['灵感与策划','故事稿','剧情分析','分集大纲','分集内容','保存与使用']:['导入内容','确认范围','故事稿','剧情分析','分集大纲','分集内容','保存与使用'];return labels.map((label,i)=>({label,stage:idea?(i===0?ideaEntryStage(p):i+1):i,current:idea?(i===0?p.stage<2:p.stage===i+1):p.stage===i}));}
function previousStage(p){return p.origin==='idea'&&p.stage===2?ideaEntryStage(p):Math.max(0,p.stage-1);}
function storyMeta(p){const m=cp(p.storyDraft||null);if(m)delete m.undo;return m;}
function ideaStoryStatus(p){if(!p.story.trim())return '尚未生成';const m=p.storyDraft;if(m?.status==='modified')return '修改后待确认'+(m.kind==='structure'?' · 结构稿':'');if(m?.kind==='structure'||!m&&(p.ideaDesk||p.story.includes('【已选策划方向'))&&p.story!==Sample.story)return '结构稿 · 待写成正文';return '已有正文'+(!m?' · 原稿保留':'');}
function ideaStoryRefine(p,text){text=text.trim();if(!text)throw Error('请写下修改要求。');const meta=storyMeta(p);p.storyDraft={kind:ideaStoryStatus(p).includes('结构稿')?'structure':'body',...(p.storyDraft||{}),status:'modified',undo:{story:p.story,meta}};p.story+='\n\n【修改要求 · 待融合】\n'+text;touch(p,'story');p.analysisConfirmed=false;}
function ideaStoryUndo(p){const u=p.storyDraft?.undo;if(!u)throw Error('没有上一版。');p.story=u.story;p.storyDraft=u.meta||undefined;touch(p,'story');p.analysisConfirmed=false;}
function characterCandidates(p){if(p.sourceAuthority)return p.importAnalysis?.kind==='demo'?cp(Sample.importDemo.characters):[];if(p.original.trim()===Sample.seed||p.original===Sample.novel)return [{name:'林澄',role:'主角',age:'',gender:'女性',personality:'细心、执着，习惯修复物件，也试图控制无法预知的变化。',background:'守着父亲留下的修理铺，擅长修复旧磁带。未来录音迫使她走出独自承担的习惯。'},{name:'阿遥',role:'重要配角',age:'',gender:'未设定',personality:'重视承诺，有自己的坚持，愿意在坦诚沟通后重新建立信任。',background:'林澄多年未见的旧友，希望在老车站关闭前取回母亲留下的信。'}];const text=p.adoptedPlan?.characters||p.story||p.original;const named=[...text.matchAll(/(?:^|[\n。；])\s*([\p{L}·]{2,16})[：:]/gu)].map(m=>m[1]).filter(n=>!['人物','世界观','核心冲突','核心设定','结局','核心亮点','动作','旁白','心理','补充要求'].includes(n));const names=[...new Set(named)];if(!names.length)return [{name:'主角（待命名）',role:'主角',age:'',gender:'未设定',personality:'待确认：主角面对故事目标时的选择与动机。',background:'建议角色 · 依据当前故事设立主要行动者，姓名、经历由你补充。',suggested:true}];return names.map((name,i)=>({name,role:i===0?'主角':i===1?'重要配角':'配角',age:'',gender:'未设定',personality:'待确认',background:'来自故事中明确标注的人物姓名；经历待确认。'}));}
function ensureCharacters(p){if(p.characters.length)return false;for(const candidate of characterCandidates(p).slice(0,2))Object.assign(addCharacter(p,candidate.name),candidate);touch(p,'analysis');p.analysisConfirmed=false;return true;}
function completeCharacters(p){const changes=[],added=[];const candidates=characterCandidates(p);for(const candidate of candidates){if(candidate.suggested&&p.characters.length)continue;let c=p.characters.find(x=>[x.name,...(x.aliases||'').split(/[、,，]/)].includes(candidate.name));if(!c){c=addCharacter(p,candidate.name);added.push(c.id);}for(const key of ['role','age','gender','personality','background']){const value=candidate[key];if(value&&!c[key]){changes.push({id:c.id,key,before:c[key],after:value});c[key]=value;}}}for(const c of p.characters)for(const [key,value]of Object.entries({role:'配角',gender:'未设定',personality:'待确认',background:c.identity&&c.identity!=='待确认身份'?c.identity:'待补充角色经历与故事中的作用。'}))if(!c[key]){changes.push({id:c.id,key,before:c[key],after:value});c[key]=value;}p.characterUndo={changes,added:added.map(id=>({id,snapshot:cp(p.characters.find(c=>c.id===id))}))};touch(p,'analysis');p.analysisConfirmed=false;return changes.length+added.length;}
function undoCharacters(p){const undo=p.characterUndo;if(!undo)throw Error('没有可撤回的角色补全。');for(const change of undo.changes){const c=p.characters.find(x=>x.id===change.id);if(c&&c[change.key]===change.after){if(change.before===undefined)delete c[change.key];else c[change.key]=change.before;}}for(const added of undo.added){const c=p.characters.find(x=>x.id===added.id);if(!c)continue;const expected=cp(added.snapshot);for(const change of undo.changes.filter(x=>x.id===added.id)){if(change.before===undefined)delete expected[change.key];else expected[change.key]=change.before;}const referenced=p.outline.some(e=>(e.characterIds||[]).includes(c.id))||Object.values(p.scripts).some(s=>s.scenes.some(x=>(x.characterIds||[]).includes(c.id)));if(!referenced&&JSON.stringify(c)===JSON.stringify(expected))p.characters=p.characters.filter(x=>x.id!==c.id);}delete p.characterUndo;touch(p,'analysis');p.analysisConfirmed=false;}

function outlineRecommendation(p){const text=p.story||p.original,events=text.split(/[。！？.!?\n]+/).filter(s=>s.trim().length>8).length,conflicts=(text.match(/但是|却|必须|冲突|阻|秘密|代价|求救|失踪|but|however/gi)||[]).length,characters=p.characters.length;const count=Math.max(1,Math.min(12,Math.ceil(events/3)+Math.min(3,conflicts)+Math.ceil(characters/3)));return {count,mode:count<=3?'compact':count>=8?'expanded':'standard',reason:`${events}段事件线索 · ${conflicts}处冲突线索 · ${characters}位角色`};}
function outlineSettings(p){const r=outlineRecommendation(p);return {mode:r.mode,count:p.outline.length||r.count,minutes:3,coverage:'adapt',...(p.outlineSettings||{})};}
function stageGroups(p){const episodes=p.outline;if(!episodes.length)return [];const n=Math.min(4,episodes.length),definitions=n===1?[['完整故事','建立目标、经历变化并回应结局']]:n===2?[['开局','建立目标与冲突'],['收束','推进抉择并回应结局']]:n===3?[['开局','目标与触发事件'],['发展','阻力、行动与转折'],['收束','最终选择与结果']]:[['开局','目标与触发事件'],['发展','尝试、阻力与关系变化'],['转折','代价与关键选择'],['收束','回应目标与结果']];let groups=definitions.map(([label,hint],i)=>({id:'phase-'+i,label,hint,episodes:[]}));const weights=episodes.map(e=>Math.max(1,count(e.events||'')+((e.change||'').length)+((e.ending||'').length))),total=weights.reduce((a,b)=>a+b,0);let phase=0,used=0;episodes.forEach((e,i)=>{const remaining=episodes.length-i,needed=n-phase;if(phase<n-1&&groups[phase].episodes.length&&(used>=total*([.18,.65,.84][phase]||1)||remaining===needed-1))phase++;groups[phase].episodes.push(e);used+=weights[i];});groups=groups.filter(g=>g.episodes.length);return groups.map(g=>{const old=p.outlinePhases?.find(x=>x.id===g.id),first=g.episodes[0];return {...g,sourceRefs:g.episodes.flatMap(e=>cp(e.sourceRefs||[])),title:old?.title||first.title||g.hint,direction:old?.direction||g.episodes.map(e=>e.events).join('\n\n'),start:episodes.indexOf(first)+1,end:episodes.indexOf(g.episodes.at(-1))+1};});}
function outlineSnapshot(p){return cp({outline:p.outline,outlinePhases:p.outlinePhases||[],selectedPhase:p.selectedPhase,selectedEpisode:p.selectedEpisode,settings:{...outlineSettings(p),count:p.outline.length||outlineSettings(p).count},basis:p.outlineBasis,archivedScripts:p.archivedScripts||{},scripts:p.scripts});}
